// Generated by prepare_submissions.py --status <file.csv>. Do not edit; regenerate from the CSV.
// Sets the team fields of existing submission items. It never creates links and never changes
// submission_model_status. Running it twice gives the same result.
assert session.sessionResource.URI.toString().toLowerCase().contains('/fsae-2027-electric-arcadia/'): 'Only the disposable acceptance project is permitted'
assert api.layer('SA').system.summary == 'FSAE2027:bootstrap-v1': 'Missing the acceptance project marker'
def req = api.requirements()
assert req.available() && req.viewpointEnabled()
def module = req.find(@@MODULE_ID@@)
assert module != null: 'The submission module is missing'
def statuses = @@STATUSES@@
def rows = @@ROWS@@
def items = req.requirements(module).collectEntries { [(it.ReqIFIdentifier): it] }
rows.each { row ->
    assert items.containsKey(row.id): 'Unknown submission item ' + row.id
    assert !row.values.containsKey('submission_status') || row.values.submission_status in statuses
    assert row.values.keySet().every { it in ['submission_status', 'submission_owner', 'submission_due', 'submission_value', 'submission_evidence_ref'] }
}
def changed = 0
api.batch('Update submission status') {
    rows.each { row ->
        def current = req.attributes(items[row.id])
        row.values.each { key, value ->
            if (current[key] != value) { req.setAttribute(items[row.id], key, value); changed++ }
        }
    }
}
log.info('Submission status updated: ' + rows.size() + ' items, ' + changed + ' values changed.')
return [items: rows.size(), changed: changed]
